sp_widget.client_script:
api.controller = function($location) {
    var c = this;

    c.goBack = function() {
        $location.search('id', 'x_839216_public_0_my_requests');
    };

    c.getStatusClass = function(status) {
        if (!status) return 'label-default';
        var s = status.toLowerCase();
        if (s === 'approved') return 'label-success';
        if (s === 'in_progress' || s === 'in progress') return 'label-warning';
        if (s === 'rejected') return 'label-danger';
        if (s === 'submitted') return 'label-info';
        return 'label-default';
    };

    c.getPriorityClass = function(priority) {
        if (!priority) return 'label-default';
        var p = priority.toLowerCase();
        if (p === 'critical') return 'label-danger';
        if (p === 'high') return 'label-warning';
        if (p === 'medium') return 'label-info';
        return 'label-default';
    };
};

sp_widget.css:
.sp-detail-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 24px;
    flex-wrap: wrap;
}
.sp-detail-number {
    font-size: 26px;
    font-weight: 700;
    color: $text-color;
    margin: 0;
}
.sp-empty-state {
    padding: 64px 24px;
}
.sp-empty-icon {
    font-size: 48px;
    margin-bottom: 16px;
    display: block;
    opacity: 0.35;
    color: $text-muted;
}
.sp-empty-title {
    font-size: $font-size-large;
    font-weight: 600;
    color: $text-color;
    margin-bottom: 8px;
}

sp_widget.script:
(function() {
    data.record = null;
    data.notFound = false;

    var sysId = $sp.getParameter('sys_id');
    if (!sysId) {
        data.notFound = true;
        return;
    }

    var table = 'x_839216_public_0_health_service_request_v1';
    var gr = new GlideRecord(table);
    gr.setLimit(1);
    if (gr.get(sysId)) {
        data.record = {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') + '',
            u_citizen_name: gr.getValue('u_citizen_name') + '',
            u_email: gr.getValue('u_email') + '',
            u_phone_number: gr.getValue('u_phone_number') + '',
            u_request_type: gr.getDisplayValue('u_request_type') + '',
            u_urgency: gr.getDisplayValue('u_urgency') + '',
            u_priority: gr.getDisplayValue('u_priority') + '',
            u_status: gr.getDisplayValue('u_status') + '',
            u_approval_status: gr.getDisplayValue('u_approval_status') + '',
            assignment_group: gr.getDisplayValue('assignment_group') + '',
            u_appointment_date: gr.getDisplayValue('u_appointment_date') + '',
            u_purpose: gr.getValue('u_purpose') + '',
            u_notes: gr.getValue('u_notes') + '',
            sys_created_on: gr.getDisplayValue('sys_created_on') + '',
            sys_created_by: gr.getValue('sys_created_by') + '',
            opened_by: gr.getDisplayValue('opened_by') + ''
        };
    } else {
        data.notFound = true;
    }
})();
